export const SHOPCONSOLE_HTML="<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex\">\n<title>PickSmart admin</title>\n<style>\n:root{--navy:#0f1f3d;--navy2:#16294f;--amb:#f59e2b;--bg:#f4f6fb;--line:#dfe3ee;--ink:#17203d;--mute:#64708a;--ok:#16a34a;--er:#c62828}\n*{box-sizing:border-box}html,body{margin:0;height:100%}body{font:15px/1.45 \"Segoe UI\",system-ui,sans-serif;background:var(--bg);color:var(--ink)}\na{color:inherit}\n.top{position:sticky;top:0;z-index:20;background:var(--navy);color:#fff;display:flex;align-items:center;gap:14px;padding:10px 16px;height:54px}\n.top b{font-size:18px;white-space:nowrap}.top b i{font-style:normal;color:var(--amb)}\n.top .sp{flex:1}.top a{color:#fff;text-decoration:none;font-size:13px;border:1px solid rgba(255,255,255,.35);border-radius:8px;padding:6px 10px;white-space:nowrap}\n.wrap{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:calc(100vh - 54px)}\nnav{background:var(--navy2);color:#cfd6ea;padding:10px 8px;overflow-y:auto;position:sticky;top:54px;height:calc(100vh - 54px)}\nnav h6{margin:14px 10px 4px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#8e9cc4;font-weight:700}\nnav button{display:flex;align-items:center;justify-content:space-between;width:100%;text-align:left;border:0;background:none;color:#e8ecf8;font:inherit;padding:9px 10px;border-radius:9px;cursor:pointer}\nnav button:hover{background:rgba(255,255,255,.07)}nav button.on{background:var(--amb);color:#1c1f3a;font-weight:700}\n.bd{background:#e53935;color:#fff;border-radius:999px;font-size:11px;font-weight:700;padding:1px 7px;min-width:20px;text-align:center}nav button.on .bd{background:#1c1f3a}\nmain{padding:18px;min-width:0}\nh1{font-size:22px;margin:0 0 4px}.sub{color:var(--mute);margin:0 0 16px}\n.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}\n.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px;cursor:pointer;text-align:left;font:inherit;color:inherit;display:block;width:100%}\n.card:hover{border-color:var(--amb);box-shadow:0 4px 14px rgba(15,31,61,.1)}\n.card .n{font-size:30px;font-weight:800;line-height:1.1}.card .n.hot{color:#d9480f}.card .t{font-weight:700;margin-top:2px}.card .d{color:var(--mute);font-size:13px}\n.box{background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px;margin:12px 0}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.btn{border:0;border-radius:10px;background:var(--amb);color:#1c1f3a;font:inherit;font-weight:700;padding:8px 14px;cursor:pointer}.btn.s{background:#fff;border:1.5px solid var(--navy);color:var(--navy)}.btn.d{background:#fff;border:1.5px solid var(--er);color:var(--er)}\ntextarea{width:100%;font:inherit;border:1px solid var(--line);border-radius:10px;padding:8px}\n.mute{color:var(--mute)}.er{color:var(--er)}.ok{color:var(--ok)}\n.k{display:inline-block;border-radius:999px;background:#e8f7ee;color:#14532d;font-size:12px;font-weight:700;padding:1px 8px}.k.n{background:#fff3e0;color:#8a4b00}\niframe{width:100%;border:0;background:#fff;border-radius:12px;height:calc(100vh - 54px - 36px)}\n.fr{padding:0}.fr main{padding:0}\n.seg{display:flex;gap:6px;margin:0 0 10px;flex-wrap:wrap}.seg button{border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 12px;font:inherit;cursor:pointer}.seg button.on{background:var(--navy);color:#fff;border-color:var(--navy)}\n@media(max-width:820px){\n .wrap{display:block}\n nav{position:sticky;top:54px;height:auto;z-index:15;display:flex;overflow-x:auto;gap:4px;padding:8px;white-space:nowrap;-webkit-overflow-scrolling:touch}\n nav h6{display:none}nav button{width:auto;flex:none;gap:6px}\n main{padding:12px}iframe{height:calc(100vh - 54px - 58px - 10px)}\n}\n</style></head><body>\n<div class=\"top\"><b>pick-smart<i>.in</i> · Admin</b><span class=\"sp\"></span><a href=\"/shop\">View shop</a><a href=\"/shop/admin\" id=\"cls\">Classic admin</a></div>\n<div class=\"wrap\"><nav id=\"nv\" aria-label=\"Admin sections\"></nav><main id=\"mn\"></main></div>\n<script>\nconst $=s=>document.querySelector(s),esc=s=>String(s==null?\"\":s).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst jf=async(u,o)=>{const r=await fetch(u,o),j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||\"Something went wrong (\"+r.status+\")\");return j};\nconst post=(u,b)=>jf(u,{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify(b)});\n/* [id, label, group]. Classic tabs open the existing admin inside this page. */\nconst NAV=[[\"Home\",[[\"dash\",\"Dashboard\"]]],[\"Sales\",[[\"o\",\"Orders\"],[\"y\",\"Pay shops\"],[\"q\",\"Reports\"],[\"r\",\"Reviews\"]]],[\"Products\",[[\"p\",\"Products\"],[\"x\",\"Upload spreadsheet\"],[\"m\",\"Photos & videos\"],[\"g\",\"Pricing\"],[\"c\",\"Checklist\"]]],[\"Shop owners\",[[\"w\",\"Shop requests\"],[\"s\",\"Shop owners\"]]],[\"Discounts\",[[\"k\",\"Coupons\"],[\"n\",\"Banners\"]]],[\"Support\",[[\"sup\",\"Support inbox\"]]],[\"Customers\",[[\"u\",\"Customers\"]]],[\"System\",[[\"b\",\"Backup & restore\"]]]];\nconst BADGE={};let CUR=\"\";\nfunction nav(){$(\"#nv\").innerHTML=NAV.map(([g,it])=>`<h6>${esc(g)}</h6>`+it.map(([id,l])=>`<button data-s=\"${id}\" class=\"${CUR===id?\"on\":\"\"}\">${esc(l)}${BADGE[id]?`<span class=\"bd\">${BADGE[id]}</span>`:\"\"}</button>`).join(\"\")).join(\"\");$(\"#nv\").querySelectorAll(\"button\").forEach(b=>b.onclick=()=>go(b.dataset.s))}\nfunction go(id){CUR=id;location.hash=\"#\"+id;nav();const m=$(\"#mn\");\n if(id===\"dash\")return dash();if(id===\"sup\")return support();\n const lab=(NAV.flatMap(x=>x[1]).find(x=>x[0]===id)||[0,\"\"])[1];\n if(!$(\"#fr\")){m.innerHTML=`<iframe id=\"fr\" title=\"${esc(lab)}\"></iframe>`}\n const f=$(\"#fr\"),src=\"/shop/admin?embed=1\";if(!f.dataset.ok){f.dataset.ok=\"1\";f.src=src+\"#t=\"+id}else{try{f.contentWindow.location.hash=\"t=\"+id}catch(e){f.src=src+\"#t=\"+id}}}\nasync function counts(){const o={};\n try{const d=await jf(\"/api/shop/admin/orders?limit=10\");(d.counts||[]).forEach(c=>o[c.status]=c.n)}catch(e){}\n let rq=0;try{rq=(await jf(\"/api/shop/admin/sellreqs\")).filter(x=>!x.done&&!x.declined).length}catch(e){}\n let low=0,oos=0,tot=0;try{const r=await fetch(\"/api/shop/admin/products?limit=1000\"),j=await r.json();if(Array.isArray(j)){tot=j.length;j.forEach(p=>{if(p.stock!=null){if(p.stock<=0)oos++;else if(p.stock<=5)low++}})}}catch(e){}\n let sup=0;try{sup=(await jf(\"/api/admin/support\")).open||0}catch(e){}\n let cp=0;try{cp=(await jf(\"/api/shop/admin/coupons\")).filter(c=>c.active).length}catch(e){}\n return{o,rq,low,oos,tot,sup,cp}}\nasync function dash(){const m=$(\"#mn\");m.innerHTML='<h1>Dashboard</h1><p class=\"sub\">Loading…</p>';const C=await counts();\n BADGE.w=C.rq||\"\";BADGE.sup=C.sup||\"\";BADGE.o=(C.o.paid_claimed||0)+(C.o.paid||0)||\"\";BADGE.p=(C.low+C.oos)||\"\";nav();\n const card=(id,n,t,d,hot)=>`<button class=\"card\" data-s=\"${id}\"><div class=\"n${hot&&n?\" hot\":\"\"}\">${n}</div><div class=\"t\">${t}</div><div class=\"d\">${d}</div></button>`;\n m.innerHTML=`<h1>Dashboard</h1><p class=\"sub\">What needs you today. Tap a card to open it.</p><div class=\"cards\">\n ${card(\"o\",C.o.paid_claimed||0,\"Payments to check\",\"Customer says they paid\",1)}\n ${card(\"o\",C.o.paid||0,\"Paid orders\",\"Ready to pack and send\",1)}\n ${card(\"o\",C.o.packed||0,\"Packed by shops\",\"Waiting for pickup\",0)}\n ${card(\"w\",C.rq,\"Shop requests\",\"New shops asking to join\",1)}\n ${card(\"sup\",C.sup,\"Support messages\",\"Not opened yet\",1)}\n ${card(\"p\",C.low,\"Low stock\",\"5 or fewer left\",1)}\n ${card(\"p\",C.oos,\"Sold out\",\"Stock is 0\",0)}\n ${card(\"k\",C.cp,\"Live coupons\",\"Switched on\",0)}\n </div><div class=\"box\"><div class=\"row\"><b>Products in the shop</b><span class=\"mute\">${C.tot}</span></div><p class=\"mute\" style=\"margin:6px 0 0\">Everything else (pricing, reports, backup) is in the menu. The old admin stays available under \"Classic admin\" at the top.</p></div>`;\n m.querySelectorAll(\".card\").forEach(b=>b.onclick=()=>go(b.dataset.s))}\nlet SF=\"open\";\nasync function support(){const m=$(\"#mn\");m.innerHTML='<h1>Support inbox</h1><p class=\"sub\">Loading…</p>';let r;try{r=await jf(\"/api/admin/support\")}catch(e){m.innerHTML='<h1>Support inbox</h1><p class=\"er\">'+esc(e.message)+\"</p>\";return}\n if(r.missing){m.innerHTML='<h1>Support inbox</h1><p class=\"er\">Support inbox is not set up yet (run migration-support.sql).</p>';return}\n if(r.open){try{await post(\"/api/admin/support\",{markRead:true})}catch(e){}BADGE.sup=\"\";nav()}\n const L=r.items||[],shown=L.filter(x=>SF===\"all\"||(SF===\"open\"?!x.status:!!x.status)),when=t=>t?new Date(t).toLocaleString(\"en-IN\",{day:\"numeric\",month:\"short\",hour:\"2-digit\",minute:\"2-digit\"}):\"\";\n m.innerHTML=`<h1>Support inbox</h1><p class=\"sub\">Messages from the Help chat. Reply sends an email to the shopper.</p><div class=\"seg\"><button data-f=\"open\" class=\"${SF===\"open\"?\"on\":\"\"}\">To do (${L.filter(x=>!x.status).length})</button><button data-f=\"done\" class=\"${SF===\"done\"?\"on\":\"\"}\">Done (${L.filter(x=>x.status).length})</button><button data-f=\"all\" class=\"${SF===\"all\"?\"on\":\"\"}\">All</button></div>`+\n (shown.length?shown.map(x=>`<div class=\"box\" data-id=\"${x.id}\"><div class=\"row\"><b>${esc(x.name||\"-\")}</b><span class=\"mute\">${esc(x.email)}</span><span class=\"mute\" style=\"margin-left:auto\">${when(x.created_at)}</span></div>\n <p style=\"margin:8px 0;white-space:pre-wrap\">${/^PRODUCT REQUEST:/.test(x.message)?'<span class=\"k n\">Product request</span> '+esc(x.message.replace(/^PRODUCT REQUEST:\\s*/,\"\")):esc(x.message)}</p>${x.page?`<div class=\"mute\" style=\"font-size:12px\">Page: ${esc(x.page)}</div>`:\"\"}\n ${x.reply?`<div style=\"margin-top:8px;padding:8px 10px;border-left:4px solid var(--ok);background:#effaf2\"><b>You replied ${when(x.replied_at)}:</b><br>${esc(x.reply)}</div>`:\"\"}\n <div class=\"rp\" hidden><textarea rows=\"6\" aria-label=\"Your reply\">${esc(\"Hi \"+(x.name||\"\")+\",\\n\\n\\n\\nThanks,\\nPickSmart Support\")}</textarea><p class=\"er\" role=\"alert\"></p><div class=\"row\"><button class=\"btn\" data-a=\"send\">Send email</button><button class=\"btn s\" data-a=\"cancel\">Cancel</button><a class=\"mute\" href=\"mailto:${esc(x.email)}?subject=${encodeURIComponent(\"Re: your PickSmart question\")}\">Open in email app</a></div></div>\n <div class=\"row\" style=\"margin-top:10px\"><button class=\"btn s\" data-a=\"reply\">${x.reply?\"Reply again\":\"Reply\"}</button><button class=\"btn s\" data-a=\"done\">${x.status?\"Mark as to do\":\"Mark done\"}</button><button class=\"btn d\" data-a=\"del\">Delete</button></div></div>`).join(\"\"):'<div class=\"box mute\">Nothing here.</div>');\n m.querySelectorAll(\".seg button\").forEach(b=>b.onclick=()=>{SF=b.dataset.f;support()});\n m.querySelectorAll(\".box[data-id]\").forEach(bx=>{const id=+bx.dataset.id,x=L.find(y=>y.id===id);bx.querySelectorAll(\"[data-a]\").forEach(b=>b.onclick=async()=>{const a=b.dataset.a;\n  if(a===\"reply\"){bx.querySelector(\".rp\").hidden=false;return}if(a===\"cancel\"){bx.querySelector(\".rp\").hidden=true;return}\n  try{if(a===\"send\"){b.disabled=true;await post(\"/api/admin/support-reply\",{id,body:bx.querySelector(\"textarea\").value})}else if(a===\"done\")await post(\"/api/admin/support\",{id,status:x.status?0:1});else if(a===\"del\"){if(!confirm(\"Delete this message for good? This cannot be undone.\"))return;await post(\"/api/admin/support\",{id,delete:true})}support()}catch(e){const p=bx.querySelector(\".rp .er\");if(p){p.textContent=e.message;b.disabled=false}else alert(e.message)}})})}\naddEventListener(\"hashchange\",()=>{const h=location.hash.slice(1);if(h&&h!==CUR&&NAV.some(g=>g[1].some(i=>i[0]===h)))go(h)});\n(async()=>{nav();const h=location.hash.slice(1);go(NAV.some(g=>g[1].some(i=>i[0]===h))?h:\"dash\");if(CUR!==\"dash\"){counts().then(C=>{BADGE.w=C.rq||\"\";BADGE.sup=C.sup||\"\";BADGE.o=(C.o.paid_claimed||0)+(C.o.paid||0)||\"\";BADGE.p=(C.low+C.oos)||\"\";nav()})}})();\n</script></body></html>\n";
